package com.gittexplorer.documentextractor.exception;
import static org.springframework.test.web.servlet.request.MockMvcRequestBuilders.multipart;import static org.springframework.test.web.servlet.result.MockMvcResultMatchers.jsonPath;import static org.springframework.test.web.servlet.result.MockMvcResultMatchers.status;
import com.gittexplorer.documentextractor.controller.DocumentController;import com.gittexplorer.documentextractor.service.DocumentService;import org.junit.jupiter.api.Test;import org.mockito.Mockito;import org.springframework.http.MediaType;import org.springframework.mock.web.MockMultipartFile;import org.springframework.test.web.servlet.MockMvc;import org.springframework.test.web.servlet.setup.MockMvcBuilders;
class GlobalExceptionHandlerTest { @Test void mapsInvalidUploadToBadRequest() throws Exception { DocumentService svc=Mockito.mock(DocumentService.class); Mockito.when(svc.extract(Mockito.any())).thenThrow(new InvalidUploadException("bad upload")); MockMvc mvc=MockMvcBuilders.standaloneSetup(new DocumentController(svc)).setControllerAdvice(new GlobalExceptionHandler()).build(); mvc.perform(multipart("/api/v1/documents/extract").file(new MockMultipartFile("files","a.txt",MediaType.TEXT_PLAIN_VALUE,"x".getBytes()))).andExpect(status().isBadRequest()).andExpect(jsonPath("$.message").value("bad upload")); } }
